mapper.update:
update user
name = #{name}, phone = #{phone}, sex = #{sex}, id_number = #{idNumber}, avatar = #{avatar}, status = #{status},
where id = #{id}

mapper.select:
select id, name, phone, sex, status, create_time from user

    id > #{lastId} and id <= #{snapshot.maxId}
    and name like concat('%', #{snapshot.name}, '%')
    and phone like concat('%', #{snapshot.phone}, '%')
    and status = #{snapshot.dataStatus}
    and create_time >= #{snapshot.startTime}
    and create_time <= #{snapshot.endTime}

order by id
limit #{limit}
